'use strict';
(function(){
 const T=JourneyTree;
 const map=mapView;mapView=function(){map();if(!S||S.training||S.tutorialReplay)return;const layer=T.midLayer(JourneyActs.act(S));for(const n of S.map[layer]||[]){const el=document.querySelector('.map-node[data-id="'+n.id+'"]');if(el){el.classList.add('cp3-tree-stop');el.insertAdjacentHTML('beforeend','<span class="cp3-tree-star" aria-hidden="true">✦</span>');el.setAttribute('aria-label',(el.getAttribute('aria-label')||'')+' · '+L('Skill Tree opens after this fight','A árvore abre após esta luta'));}}};
 const legend=mapLegend;mapLegend=function(){legend();const body=document.querySelector('.act-legend-scroll')||document.querySelector('#overlay>.modal');body?.insertAdjacentHTML('beforeend','<p>✦ '+L('After the sixth fight of each map, a Skill Tree window opens. Spent XP permanently unlocks nodes; remaining XP carries within this run and is lost when it ends.','Após a sexta luta de cada mapa, uma janela da árvore abre. O XP gasto desbloqueia nós permanentemente; a sobra segue nesta run e é perdida ao encerrá-la.')+'</p>');};
 function totals(){const t=S?.journey?.tree;return {gained:t?.gain||0,spent:t?.spent||0,lost:t?.lost||0};}
 const result=resultView;resultView=function(){result();if(!S?.meta?.ended||S.training||S.tutorialReplay)return;const xp=S.meta.treeXp||totals();document.querySelector('#screen-content')?.insertAdjacentHTML('beforeend','<section class="cp3-xp-result"><h3>'+L('Run XP','XP da run')+'</h3><div><span>'+L('Earned','Ganho')+' <b>'+xp.gained+'</b></span><span>'+L('Spent','Gasto')+' <b>'+xp.spent+'</b></span><span>'+L('Lost','Perdido')+' <b>'+xp.lost+'</b></span></div></section>');};
 const menu=journeyMenu;journeyMenu=function(){menu();const abandon=document.querySelector('#overlay [data-act="abandon-confirm"]');if(abandon)abandon.insertAdjacentHTML('afterend','<small class="cp3-abandon-note">'+L('Abandoning loses unspent XP. Purchased tree nodes remain.','Abandonar perde o XP não gasto. Os nós comprados da árvore permanecem.')+'</small>');};
})();
